#include "engine/ai_controller.hpp"
#include <iomanip>
#include <sstream>
#include <set>
namespace engine {
namespace {
void require(bool b,const std::string& m){if(!b)throw std::invalid_argument(m);}
void key(std::string_view s){require(!s.empty()&&s.size()<=256,"Invalid AI binding/parameter key");for(unsigned char c:s)require(c>32&&c!=127,"Invalid AI key character");}
void value(const AiParameter& p,const AiValue& v){
    require(std::size_t(p.type)==v.index(),"Wrong type for AI parameter "+p.key);
    if(auto* n=std::get_if<double>(&v))require(std::isfinite(*n)&&*n>=p.minimum&&*n<=p.maximum,"AI number outside schema: "+p.key);
    if(auto* n=std::get_if<Vec3>(&v))for(float x:{n->x,n->y,n->z})require(std::isfinite(x)&&x>=p.minimum&&x<=p.maximum,"AI vector outside schema: "+p.key);
    if(auto* s=std::get_if<std::string>(&v))require(s->empty()||Node::validSavedId(*s),"Invalid AI actor reference");
}
void schema(const std::vector<AiParameter>& parameters){require(parameters.size()<=16,"Too many AI parameters");std::set<std::string> seen;for(const auto& p:parameters){key(p.key);require(seen.insert(p.key).second&&std::isfinite(p.minimum)&&std::isfinite(p.maximum)&&p.minimum<=p.maximum,"Invalid AI parameter schema");value(p,p.initial);}}
void writeBinding(std::ostream& o,const AiBinding& b){o<<std::quoted(b.key)<<' '<<b.parameters.size()<<'\n';for(const auto&[k,v]:b.parameters){o<<std::quoted(k)<<' '<<v.index()<<' ';std::visit([&](const auto& x){using T=std::decay_t<decltype(x)>;if constexpr(std::is_same_v<T,Vec3>)o<<x.x<<' '<<x.y<<' '<<x.z;else if constexpr(std::is_same_v<T,std::string>)o<<std::quoted(x);else o<<x;},v);o<<'\n';}}
AiBinding readBinding(std::istream& in){AiBinding b;std::size_t count=0;require(bool(in>>std::quoted(b.key)>>count)&&count<=16,"Invalid AI binding payload");for(std::size_t i=0;i<count;++i){std::string k;unsigned type=0;require(bool(in>>std::quoted(k)>>type)&&type<=3,"Invalid AI parameter payload");AiValue v;switch(type){case 0:{unsigned x;require(bool(in>>x)&&x<=1,"Invalid AI boolean");v=bool(x);break;}case 1:{double x;require(bool(in>>x),"Invalid AI number");v=x;break;}case 2:{Vec3 x;require(bool(in>>x.x>>x.y>>x.z),"Invalid AI vector");v=x;break;}default:{std::string x;require(bool(in>>std::quoted(x)),"Invalid AI reference");v=x;}}
    require(b.parameters.emplace(k,std::move(v)).second,"Duplicate AI parameter");}return b;}
}
std::shared_ptr<const AiBindingRegistry> AiBindingRegistry::create(std::vector<AiBehaviorBinding> behaviors,std::vector<AiConditionBinding> conditions){
    require(behaviors.size()<=128&&conditions.size()<=128,"AI registry capacity exceeded");std::set<std::string> keys;
    for(const auto& b:behaviors){key(b.key);schema(b.parameters);require(keys.insert(b.key).second,"Duplicate AI behavior binding");}keys.clear();
    for(const auto& c:conditions){key(c.key);schema(c.parameters);require(keys.insert(c.key).second&&bool(c.evaluate),"Invalid AI condition binding");}
    auto r=std::shared_ptr<AiBindingRegistry>(new AiBindingRegistry);r->behaviors_=std::move(behaviors);r->conditions_=std::move(conditions);return r;
}
const AiBehaviorBinding& AiBindingRegistry::behavior(std::string_view k)const{for(const auto& b:behaviors_)if(b.key==k)return b;throw std::invalid_argument("Missing AI behavior binding: "+std::string(k));}
const AiConditionBinding& AiBindingRegistry::condition(std::string_view k)const{for(const auto& b:conditions_)if(b.key==k)return b;throw std::invalid_argument("Missing AI condition binding: "+std::string(k));}
AiBinding AiBindingRegistry::defaults(std::string_view k,bool c)const{AiBinding b;b.key=k;const auto& ps=c?condition(k).parameters:behavior(k).parameters;for(const auto& p:ps)b.parameters[p.key]=p.initial;return b;}
void AiBindingRegistry::validate(const AiBinding& b,bool c)const{const auto& ps=c?condition(b.key).parameters:behavior(b.key).parameters;require(ps.size()==b.parameters.size(),"AI parameters do not match binding schema: "+b.key);for(const auto& p:ps){auto it=b.parameters.find(p.key);require(it!=b.parameters.end(),"Missing AI parameter: "+p.key);value(p,it->second);}}
std::shared_ptr<const AiBindingRegistry> AiBindingRegistry::builtins(){static auto result=create({
    {"idle",{},false,[](AiControllerComponent& c,const AiBinding&,double){if(auto* m=c.motor())m->stop();}, {},{}},
    {"move",{{"velocity",AiParameterType::Vector,Vec3{1,0,0},-100,100}},true,{},[](AiControllerComponent& c,const AiBinding& b,double){auto* m=c.motor();if(!m)throw std::runtime_error("AI move binding requires a motor");m->submitMovement({std::get<Vec3>(b.parameters.at("velocity")),false});},{}}
},{
    {"always",{},[](AiControllerComponent&,const AiBinding&){return true;}},
    {"flag",{{"value",AiParameterType::Boolean,false}},[](AiControllerComponent&,const AiBinding& b){return std::get<bool>(b.parameters.at("value"));}},
    {"near",{{"target",AiParameterType::Actor,std::string{}},{"distance",AiParameterType::Number,2.0,0,10000}},[](AiControllerComponent& c,const AiBinding& b){auto* target=c.resolveActor(std::get<std::string>(b.parameters.at("target")));if(!target||!c.owner())return false;auto d=transformPoint(target->worldMatrix(),{})-transformPoint(c.owner()->worldMatrix(),{});auto range=std::get<double>(b.parameters.at("distance"));return double(dot(d,d))<=range*range;}}
});return result;}
AiControllerSettings AiControllerSettings::defaults(std::shared_ptr<const StateMachineDefinition> graph,const AiBindingRegistry& r){require(bool(graph),"Missing controller graph");AiControllerSettings s;s.graph=std::move(graph);for(const auto& state:s.graph->data().states)s.states[state.id]=r.defaults(state.behavior);for(const auto& t:s.graph->data().transitions)s.conditions[t.condition]=r.defaults(t.condition,true);return s;}
void AiControllerSettings::validate(const AiBindingRegistry& r)const{require(bool(graph),"Missing controller graph");require(states.size()==graph->data().states.size(),"Controller state bindings do not match graph");std::set<std::string> keys;for(const auto& s:graph->data().states){auto it=states.find(s.id);require(it!=states.end(),"Missing controller state binding");r.validate(it->second);}for(const auto& t:graph->data().transitions)keys.insert(t.condition);require(keys.size()==conditions.size(),"Controller condition bindings do not match graph");for(const auto& k:keys){auto it=conditions.find(k);require(it!=conditions.end(),"Missing controller condition binding: "+k);r.validate(it->second,true);}}
AiControllerComponent::AiControllerComponent(std::string name,AiControllerSettings settings,std::shared_ptr<const AiBindingRegistry> registry):Component(std::move(name)),settings_(std::move(settings)),registry_(std::move(registry)){require(bool(registry_),"Missing AI binding registry");settings_.validate(*registry_);machine_=std::make_unique<StateMachine>(settings_.graph);setFixedTickEnabled(true);}
CharacterMotorComponent* AiControllerComponent::motor()const{return const_cast<CharacterMotorComponent*>(getComponent<CharacterMotorComponent>());}
Actor* AiControllerComponent::resolveActor(std::string_view id)const{if(!scene()||id.empty())return nullptr;auto* a=dynamic_cast<Actor*>(const_cast<Scene*>(scene())->findSavedNode(id));return a&&a->isActiveInHierarchy()?a:nullptr;}
void AiControllerComponent::validateReferences(const Scene& scene)const{for(const auto* map:{&settings_.conditions})for(const auto&[k,b]:*map)for(const auto&[p,v]:b.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI actor reference: "+*id);for(const auto&[k,b]:settings_.states)for(const auto&[p,v]:b.parameters)if(auto* id=std::get_if<std::string>(&v);id&&!id->empty())require(dynamic_cast<const Actor*>(scene.findSavedNode(*id))!=nullptr,"Missing AI actor reference: "+*id);}
void AiControllerComponent::validate()const{Component::validate();settings_.validate(*registry_);if(!owner()){require(!scene(),"AI controller requires an actor owner");return;}require(parent()==owner(),"AI controllers must be direct actor components");require(owner()->getComponents<AiControllerComponent>().size()==1,"Only one AI controller may own an actor");for(const auto&[id,b]:settings_.states)if(registry_->behavior(b.key).needsMotor){require(motor()!=nullptr,"AI movement requires a CharacterMotorComponent");if(auto it=b.parameters.find("velocity");it!=b.parameters.end()&&motor()->settings().collisionAware)if(auto* v=std::get_if<Vec3>(&it->second))require(v->y==0,"Collision-aware AI velocity must have Y=0");}}
void AiControllerComponent::configure(AiControllerSettings settings){settings.validate(*registry_);auto next=std::make_unique<StateMachine>(settings.graph);auto old=settings_;settings_=settings;try{validate();if(scene())validateReferences(*scene());}catch(...){settings_=std::move(old);throw;}settings_=std::move(old);stop();settings_=std::move(settings);machine_=std::move(next);transitions_.clear();simulationSeconds_=0;hasPrevious_=false;error_.clear();}
void AiControllerComponent::stop()noexcept{try{machine_->stop(*this);}catch(...){}if(auto* m=motor())m->stop();}
void AiControllerComponent::restart(){validate();if(scene())validateReferences(*scene());machine_->restart(*this,settings_.graph,settings_.graph->data().initial);error_.clear();transitions_.clear();hasPrevious_=false;simulationSeconds_=0;}
void AiControllerComponent::enter(const AiState& s){if(hasPrevious_){if(transitions_.size()==32)transitions_.erase(transitions_.begin());transitions_.push_back({previous_,s.id,simulationSeconds_});}previous_=s.id;hasPrevious_=true;const auto& b=settings_.states.at(s.id);auto& entry=registry_->behavior(b.key);if(entry.enter)entry.enter(*this,b,0);}
void AiControllerComponent::update(const AiState& s,double dt){const auto& b=settings_.states.at(s.id);const auto& entry=registry_->behavior(b.key);if(entry.update)entry.update(*this,b,dt);}
void AiControllerComponent::exit(const AiState& s)noexcept{try{const auto& b=settings_.states.at(s.id);const auto& entry=registry_->behavior(b.key);if(entry.exit)entry.exit(*this,b,0);}catch(...){error_="AI exit callback failed";}if(auto* m=motor())m->stop();}
bool AiControllerComponent::condition(std::string_view k){const auto& b=settings_.conditions.at(std::string(k));return registry_->condition(b.key).evaluate(*this,b);}
void AiControllerComponent::fixedTick(double dt){try{validate();simulationSeconds_+=dt;machine_->step(*this,dt);}catch(const std::exception& e){error_=e.what();stop();}}
std::string AiControllerArchive::save(const AiControllerSettings& s){require(bool(s.graph),"Missing AI graph");std::ostringstream out;out.imbue(std::locale::classic());out<<std::setprecision(17)<<"AIC 1\n"<<std::quoted(StateMachineArchive::save(*s.graph))<<'\n'<<s.states.size()<<' '<<s.conditions.size()<<'\n';for(const auto&[id,b]:s.states){out<<id<<' ';writeBinding(out,b);}for(const auto&[k,b]:s.conditions){out<<std::quoted(k)<<' ';writeBinding(out,b);}return out.str();}
AiControllerSettings AiControllerArchive::load(std::string_view bytes,const AiBindingRegistry& r){require(bytes.size()<=2097152,"AI controller payload exceeds 2 MiB");std::istringstream in{std::string(bytes)};in.imbue(std::locale::classic());std::string magic,graph;unsigned version;std::size_t ns,nc;require(bool(in>>magic>>version>>std::quoted(graph))&&magic=="AIC"&&version==1,"Invalid AI controller payload");AiControllerSettings s;s.graph=StateMachineArchive::load(graph);require(bool(in>>ns>>nc)&&ns<=256&&nc<=1024,"Invalid controller binding counts");for(std::size_t i=0;i<ns;++i){std::uint32_t id;require(bool(in>>id),"Invalid controller state ID");require(s.states.emplace(id,readBinding(in)).second,"Duplicate controller state binding");}for(std::size_t i=0;i<nc;++i){std::string k;require(bool(in>>std::quoted(k)),"Invalid controller condition");require(s.conditions.emplace(k,readBinding(in)).second,"Duplicate controller condition binding");}in>>std::ws;require(in.eof(),"Unexpected controller payload suffix");s.validate(r);return s;}
ComponentCodecs aiControllerCodecs(std::shared_ptr<const AiBindingRegistry> registry){require(bool(registry),"Missing controller codec registry");ComponentCodecs codecs;codecs.add({"engine.ai.controller",typeid(AiControllerComponent),1,[](const Component& c){const auto& ai=dynamic_cast<const AiControllerComponent&>(c);ai.validate();if(ai.scene())ai.validateReferences(*ai.scene());const auto text=AiControllerArchive::save(ai.settings());return std::vector<std::byte>(reinterpret_cast<const std::byte*>(text.data()),reinterpret_cast<const std::byte*>(text.data()+text.size()));},[registry](std::uint32_t version,std::span<const std::byte> bytes){require(version==1,"Unsupported AI controller codec");return std::make_unique<AiControllerComponent>("AI controller",AiControllerArchive::load(std::string_view(reinterpret_cast<const char*>(bytes.data()),bytes.size()),*registry),registry);},[](Component& c,Scene& s){auto& ai=dynamic_cast<AiControllerComponent&>(c);ai.validate();ai.validateReferences(s);}});return codecs;}
} // namespace engine
